  for i,p in enumerate(pp):
   steps=q.get('steps',[]);steps=steps or [q.get('referenceAnswer','')]
   if p['type']=='choice':fs.append(ch(p.get('label',str(i+1)),p.get('label','Select the result.'),p['answer'],p['options'],steps))
   else:fs.append(nu(p.get('label',str(i+1)),p['answer'],steps))
  put(q['id'],None,fs)
