def calcfield(l,expr,env):
 import ast
 details=[]
 def walk(node):
  if isinstance(node,(ast.Name,ast.Constant)):return eval(compile(ast.Expression(node),'','eval'),{},env)
  if isinstance(node,ast.Attribute):
   base=walk(node.value)
   val=getattr(base,node.attr)
   if node.attr=='T':details.append('Transpose '+tex(base)+' by interchanging rows and columns to obtain '+tex(val)+'.')
   return val
  if isinstance(node,ast.UnaryOp):
   a=walk(node.operand);v=-a
   details.append('Negate each entry of '+tex(a)+'.')
   return v
  if isinstance(node,ast.BinOp):
   a=walk(node.left);b=walk(node.right)
   if isinstance(node.op,ast.Add):v=a+b;rule='Add corresponding entries'
   elif isinstance(node.op,ast.Sub):v=a-b;rule='Subtract corresponding entries'
   elif isinstance(node.op,ast.Mult):
    v=a*b
    if isinstance(a,s.MatrixBase) and isinstance(b,s.MatrixBase):
     dot='+'.join('('+s.latex(a[0,k])+')('+s.latex(b[k,0])+')' for k in range(a.cols))
     rule='Take row–column dot products; for example the first entry is '+r'\('+dot+'='+s.latex(v[0,0])+r'\)'
    else:rule='Multiply every entry by the scalar'
   elif isinstance(node.op,ast.Div):v=a/b;rule='Divide every entry by the scalar'
   else:raise ValueError('Unsupported operation')
   details.append(rule+' in '+ast.unparse(node)+' to get '+tex(v)+'.')
   return v
  if isinstance(node,ast.Call):
   a=walk(node.args[0]);v=s.trace(a)
   details.append('The trace is the diagonal sum '+r'\('+'+'.join('('+s.latex(a[i,i])+')' for i in range(a.rows))+'='+s.latex(v)+r'\)'+'.')
   return v
  raise ValueError('Unsupported expression')
 try:
  v=walk(ast.parse(expr,mode='eval').body)
  return mc(l,v,details,'Select the exact matrix.' if isinstance(v,s.MatrixBase) else 'Enter the scalar result.')
 except (s.matrices.exceptions.ShapeError,s.matrices.exceptions.NonSquareMatrixError,ValueError) as e:
  return ch(l,'Select the result.','Undefined',['Zero','Identity'],details+['Check dimensions in '+expr+'. '+str(e),'This expression is undefined: addition requires equal sizes, multiplication requires matching inner dimensions, and trace requires a square matrix.'])

