 if A.det()==0:return ch(l,'Select the inverse result.','No inverse exists',['The inverse is the identity.','The inverse is the zero matrix.'],['Row reduction of [A|I] gives '+tex(rr)+'.','The left block has a missing pivot, so A is singular.'])
 v=A.inv();assert A*v==s.eye(A.rows) and v*A==s.eye(A.rows)
 return mc(l,v,['Start with [A|I]='+tex(aug)+'.','Apply elementary row operations until the left block is I; the result is '+tex(rr)+'.','The right block is A inverse. A direct product with A is I.'])
